-- WordSell inventory foundation. Runtime initialization mirrors this idempotent PostgreSQL schema.
CREATE TABLE IF NOT EXISTS component_types (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, position INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_components (id TEXT PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, component_type_id TEXT REFERENCES component_types(id), unit TEXT NOT NULL DEFAULT 'unit', recoverable BOOLEAN NOT NULL DEFAULT TRUE, active BOOLEAN NOT NULL DEFAULT TRUE, reorder_level DOUBLE PRECISION NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_products (id TEXT PRIMARY KEY, shopify_product_id TEXT NOT NULL, shopify_variant_id TEXT NOT NULL UNIQUE, inventory_item_id TEXT NOT NULL DEFAULT '', sku TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, variant_title TEXT NOT NULL DEFAULT '', vendor TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE, raw_json TEXT NOT NULL DEFAULT '{}', synced_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipe_versions (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES inventory_products(id) ON DELETE CASCADE, version INTEGER NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(product_id, version));
CREATE TABLE IF NOT EXISTS recipe_items (id BIGSERIAL PRIMARY KEY, recipe_version_id TEXT NOT NULL REFERENCES recipe_versions(id) ON DELETE CASCADE, component_id TEXT NOT NULL REFERENCES inventory_components(id), quantity DOUBLE PRECISION NOT NULL CHECK(quantity > 0), UNIQUE(recipe_version_id, component_id));
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', tax_id TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_orders (id TEXT PRIMARY KEY, po_number TEXT NOT NULL UNIQUE, supplier_id TEXT NOT NULL REFERENCES suppliers(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ordered','partially_received','received','closed','cancelled')), order_date TEXT NOT NULL, expected_date TEXT NOT NULL DEFAULT '', currency TEXT NOT NULL DEFAULT 'INR', notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_order_lines (id TEXT PRIMARY KEY, purchase_order_id TEXT NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE, component_id TEXT REFERENCES inventory_components(id), supplier_sku TEXT NOT NULL DEFAULT '', description TEXT NOT NULL, ordered_quantity DOUBLE PRECISION NOT NULL CHECK(ordered_quantity > 0), received_quantity DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(received_quantity >= 0), rejected_quantity DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(rejected_quantity >= 0), unit_cost DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(unit_cost >= 0), tax_rate DOUBLE PRECISION NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS goods_receipts (id TEXT PRIMARY KEY, receipt_number TEXT NOT NULL UNIQUE, purchase_order_id TEXT NOT NULL REFERENCES purchase_orders(id), received_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted','void')), notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, posted_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS goods_receipt_lines (id TEXT PRIMARY KEY, goods_receipt_id TEXT NOT NULL REFERENCES goods_receipts(id) ON DELETE CASCADE, purchase_order_line_id TEXT NOT NULL REFERENCES purchase_order_lines(id), component_id TEXT NOT NULL REFERENCES inventory_components(id), accepted_quantity DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(accepted_quantity >= 0), rejected_quantity DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(rejected_quantity >= 0), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS supplier_invoices (id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), purchase_order_id TEXT REFERENCES purchase_orders(id), invoice_number TEXT NOT NULL, invoice_date TEXT NOT NULL DEFAULT '', storage_key TEXT NOT NULL DEFAULT '', original_filename TEXT NOT NULL DEFAULT '', file_hash TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'uploaded' CHECK(status IN ('uploaded','extracting','review_required','matched','approved','rejected')), extracted_json TEXT NOT NULL DEFAULT '{}', subtotal DOUBLE PRECISION NOT NULL DEFAULT 0, tax_total DOUBLE PRECISION NOT NULL DEFAULT 0, grand_total DOUBLE PRECISION NOT NULL DEFAULT 0, created_by TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(supplier_id, invoice_number));
CREATE TABLE IF NOT EXISTS supplier_invoice_lines (id TEXT PRIMARY KEY, supplier_invoice_id TEXT NOT NULL REFERENCES supplier_invoices(id) ON DELETE CASCADE, purchase_order_line_id TEXT REFERENCES purchase_order_lines(id), component_id TEXT REFERENCES inventory_components(id), description TEXT NOT NULL DEFAULT '', sku TEXT NOT NULL DEFAULT '', quantity DOUBLE PRECISION NOT NULL DEFAULT 0, unit_cost DOUBLE PRECISION NOT NULL DEFAULT 0, tax_amount DOUBLE PRECISION NOT NULL DEFAULT 0, match_confidence DOUBLE PRECISION NOT NULL DEFAULT 0, match_status TEXT NOT NULL DEFAULT 'unmatched');
CREATE TABLE IF NOT EXISTS component_ledger (id BIGSERIAL PRIMARY KEY, component_id TEXT NOT NULL REFERENCES inventory_components(id), quantity_delta DOUBLE PRECISION NOT NULL, entry_type TEXT NOT NULL, reference_type TEXT NOT NULL DEFAULT '', reference_id TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', actor_id TEXT NOT NULL DEFAULT '', actor_email TEXT NOT NULL DEFAULT '', idempotency_key TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_requirement_sets (id TEXT PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, recipe_snapshot_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'complete', created_at TEXT NOT NULL, UNIQUE(order_id));
CREATE TABLE IF NOT EXISTS order_requirements (id BIGSERIAL PRIMARY KEY, requirement_set_id TEXT NOT NULL REFERENCES order_requirement_sets(id) ON DELETE CASCADE, component_id TEXT NOT NULL REFERENCES inventory_components(id), required_quantity DOUBLE PRECISION NOT NULL DEFAULT 0, allocated_quantity DOUBLE PRECISION NOT NULL DEFAULT 0, consumed_quantity DOUBLE PRECISION NOT NULL DEFAULT 0, UNIQUE(requirement_set_id, component_id));
CREATE TABLE IF NOT EXISTS provider_event_inbox (id BIGSERIAL PRIMARY KEY, provider TEXT NOT NULL, delivery_id TEXT NOT NULL, topic TEXT NOT NULL, payload_hash TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', received_at TEXT NOT NULL, processed_at TEXT NOT NULL DEFAULT '', UNIQUE(provider, delivery_id));
CREATE TABLE IF NOT EXISTS inventory_audit_events (id BIGSERIAL PRIMARY KEY, actor_id TEXT NOT NULL DEFAULT '', actor_email TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT NOT NULL DEFAULT '{}', after_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_component_ledger_component ON component_ledger (component_id, created_at);
CREATE INDEX IF NOT EXISTS idx_inventory_products_sku ON inventory_products (sku);
CREATE INDEX IF NOT EXISTS idx_purchase_orders_status ON purchase_orders (status, expected_date);
CREATE INDEX IF NOT EXISTS idx_purchase_order_lines_component ON purchase_order_lines (component_id);
CREATE INDEX IF NOT EXISTS idx_provider_event_inbox_status ON provider_event_inbox (provider, status, received_at);
